/*
  n8n Code Node: Normalization & 15% Price Delta Verification
  This node merges the fresh source data with current DB data,
  calculates price fluctuations, and outputs normalizations and alerts.
*/

// 1. Identify which input branch was used (HTTP vs Google Sheets)
// Fall back to empty array if not defined
const inputData = $input.all();
const freshItems = [];

for (const item of inputData) {
  // Handle n8n structure mapping
  const fields = item.json;
  // Standardize potential inputs from Google Sheet or public API
  const code = fields.material_code || fields.Codigo || fields.code;
  const price = parseFloat(fields.price_per_m2 || fields.Preco || fields.price || 0);
  const name = fields.display_name || fields.Nome || fields.name || code;
  const unit = fields.unit || fields.Unidade || 'm2';
  const source = fields.source_url || fields.Fonte || '';

  if (code && !isNaN(price)) {
    freshItems.push({
      material_code: code,
      display_name: name,
      price_per_m2: price,
      unit: unit,
      region: 'BR',
      updated_at: new Date().toISOString(),
      source_url: source
    });
  }
}

// 2. Fetch existing DB values from the Supabase branch (Node Index 1)
let currentDBItems = [];
try {
  currentDBItems = $items("Get Current Prices (Supabase)").map(i => i.json);
} catch (e) {
  // In case Supabase node is empty or hasn't run yet
  currentDBItems = [];
}

const dbMap = {};
currentDBItems.forEach(item => {
  dbMap[item.material_code] = parseFloat(item.price_per_m2);
});

// 3. Compute deviations and identify anomalous changes > 15%
const alerts = [];
const upsertPayload = [];

freshItems.forEach(item => {
  upsertPayload.push(item);

  const oldPrice = dbMap[item.material_code];
  if (oldPrice !== undefined && oldPrice > 0) {
    const delta = Math.abs(item.price_per_m2 - oldPrice) / oldPrice;
    if (delta > 0.15) {
      alerts.push({
        material_code: item.material_code,
        display_name: item.display_name,
        old_price: oldPrice,
        new_price: item.price_per_m2,
        percentage_change: (delta * 100).toFixed(1) + '%',
        direction: item.price_per_m2 > oldPrice ? 'AUMENTO 📈' : 'REDUÇÃO 📉'
      });
    }
  }
});

// Return structure optimized for downstream nodes:
// Output 0 (main): items to upsert to Supabase
// Output 1 (auxiliary): list of triggered alerts
return [
  upsertPayload.map(x => ({ json: x })),
  alerts.map(x => ({ json: x }))
];

// Prepare text alert summary for webhook integration
const alerts = $items("Normalize & Check Deltas", 1).map(i => i.json);

let message = "⚠️ *ALERTA DE FLUCTUACIÓN DE PRECIOS - ORBIN AI* ⚠️\n\n";
message += `Se detectaron cambios en el precio del material que superan el umbral del 15% respecto a la semana pasada:\n\n`;

alerts.forEach(a => {
  message += `• *${a.display_name}* (${a.material_code}):\n`;
  message += `  - Movimiento: ${a.direction}\n`;
  message += `  - Precio anterior: USD ${a.old_price.toFixed(2)}\n`;
  message += `  - Nuevo precio: USD ${a.new_price.toFixed(2)}\n`;
  message += `  - Desviación: ${a.percentage_change}\n\n`;
});

message += "Los nuevos precios ya se han sincronizado con Supabase y están en producción.";

return [{
  json: {
    text: message,
    raw_alerts: alerts
  }
}];
